-- HALO: check that migration 0036 is applied correctly. Read only.
-- Generated by scripts/build-apply-bundle.mjs from each migration's own verification query.
-- Expect one row: all_migrations_ok = true and failing = none.

with checks as (
  select '0036' as migration, j.key as check_name, coalesce(j.value::boolean, false) as ok
  from (
    select
        exists (select 1 from information_schema.columns
                 where table_schema = 'public' and table_name = 'profiles'
                   and column_name = 'address') as address_column_present,
        not exists (select 1 from public.profiles where address is not null)
          as address_never_written
  ) q, jsonb_each_text(to_jsonb(q)) j
)
select bool_and(ok) as all_migrations_ok,
       count(*) as checks_run,
       coalesce(string_agg(migration || '.' || check_name, ', ') filter (where not ok), 'none') as failing
from checks;
